@namespace sv_204e65baf84d4ad7b2abc2377024dec1.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due">@Task.DueDate.ToString("MMM dd")</span>

    <div class="task-actions">
        @if (ColumnIndex > 0)
        {
            <button class="btn-move" @onclick="MoveLeft" disabled="@IsMoving">← Move Left</button>
        }
        @if (ColumnIndex < 2)
        {
            <button class="btn-move" @onclick="MoveRight" disabled="@IsMoving">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter, EditorRequired] public int ColumnIndex { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }

    private bool IsMoving;

    private static readonly string[] Statuses = ["To Do", "In Progress", "Done"];

    private async System.Threading.Tasks.Task MoveLeft()
    {
        IsMoving = true;
        await OnMoveTask.InvokeAsync((Task.Id, Statuses[ColumnIndex - 1]));
        IsMoving = false;
    }

    private async System.Threading.Tasks.Task MoveRight()
    {
        IsMoving = true;
        await OnMoveTask.InvokeAsync((Task.Id, Statuses[ColumnIndex + 1]));
        IsMoving = false;
    }
}

@namespace sv_204e65baf84d4ad7b2abc2377024dec1.Components.Pages.Board

@if (!IsVisible)
{
    <button class="btn-add-task" @onclick="Show">+ Add Task</button>
}
else
{
    <div class="add-task-form">
        <input type="text" placeholder="Title" @bind="Title" />
        <input type="text" placeholder="Assignee" @bind="Assignee" />
        <select @bind="Priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
        <input type="date" @bind="DueDate" />

        @if (!string.IsNullOrEmpty(error))
        {
            <p class="form-error">@error</p>
        }

        <div class="form-actions">
            <button class="btn-save" @onclick="Save" disabled="@isSaving">Save</button>
            <button class="btn-cancel" @onclick="Cancel" disabled="@isSaving">Cancel</button>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public string DefaultStatus { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }

    private bool IsVisible;
    private string Title = "";
    private string Assignee = "";
    private string Priority = "Medium";
    private DateTime DueDate = DateTime.Today.AddDays(7);
    private string error = "";
    private bool isSaving;

    private void Show() => IsVisible = true;

    private void Cancel()
    {
        ResetForm();
        IsVisible = false;
    }

    private async Task Save()
    {
        error = "";
        if (string.IsNullOrWhiteSpace(Title) || string.IsNullOrWhiteSpace(Assignee))
        {
            error = "Title and assignee are required.";
            return;
        }

        isSaving = true;
        await OnTaskCreated.InvokeAsync((Title.Trim(), Assignee.Trim(), Priority, DueDate));
        isSaving = false;
        ResetForm();
        IsVisible = false;
    }

    private void ResetForm()
    {
        Title = "";
        Assignee = "";
        Priority = "Medium";
        DueDate = DateTime.Today.AddDays(7);
        error = "";
    }
}

@namespace sv_204e65baf84d4ad7b2abc2377024dec1.Components.Pages.Board

<div class="task-search-bar">
    <input type="text"
           placeholder="Search tasks by title..."
           value="@SearchTerm"
           @oninput="OnInput" />
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = "";
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }

    private async Task OnInput(ChangeEventArgs e)
    {
        await SearchTermChanged.InvokeAsync(e.Value?.ToString() ?? "");
    }
}

@namespace sv_204e65baf84d4ad7b2abc2377024dec1.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task" ColumnIndex="ColumnIndex" OnMoveTask="OnMoveTask" />
        }
    </div>

    <div class="column-footer">
        <AddTaskForm DefaultStatus="@ColumnName" OnTaskCreated="HandleTaskCreated" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = [];
    [Parameter, EditorRequired] public int ColumnIndex { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter, EditorRequired] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate, string Status)> OnTaskCreated { get; set; }

    private async Task HandleTaskCreated((string Title, string Assignee, string Priority, DateTime DueDate) args)
    {
        await OnTaskCreated.InvokeAsync((args.Title, args.Assignee, args.Priority, args.DueDate, ColumnName));
    }
}

